-- Data/Recipes.lua, generated by tools/update-recipes.js (docs/chronicle.md, Recipe data): its shape
-- by the format in its header, read here on its own (not through Modules/Chronicle/Recipes.lua): the
-- lines, every recipe's fields and reagents, known recipes, names in both languages.
-- Needs: no other file (it only reads the data).
local suite = ...
local check, section, ns = suite.check, suite.section, suite.ns

local D = ns.RecipeData

section("Recipe data: the lines")
check(type(D) == "table", "ns.RecipeData is there")
check(type(D.build) == "string" and D.build:match("^%d+%.%d+%.%d+%.%d+$"), "the build it came from")
local function same(list, expected)
	if #list ~= #expected then return false end
	for i, v in ipairs(expected) do
		if list[i] ~= v then return false end
	end
	return true
end
check(same(D.order, { 171, 164, 333, 202, 165, 197, 185, 129 }), "the crafting lines, in the tab's order")
check(same(D.gathering, { 182, 186, 393, 356 }), "the gathering lines")

local isLine, crafting = {}, {}
for _, line in ipairs(D.order) do isLine[line] = true; crafting[line] = true end
for _, line in ipairs(D.gathering) do isLine[line] = true end

local function names(list)
	return type(list) == "table" and #list == 2 and type(list[1]) == "string" and list[1] ~= ""
		and type(list[2]) == "string" and list[2] ~= ""
end
for line in pairs(isLine) do
	check(names(D.names[line]), "line " .. line .. " is named in both languages")
	check(type(D.icons[line]) == "number" and D.icons[line] > 0, "line " .. line .. " has an icon")
	check((crafting[line] == true) == (D.recipes[line] ~= nil), "line " .. line .. " has recipes if it's a crafting line")
end
local children, covered = 0, {}
for child, base in pairs(D.parents) do
	children = children + 1
	covered[base] = true
	check(isLine[base] and not isLine[child], "child line " .. child .. " leads to a base line")
end
check(children == 12, "12 child lines")
for line in pairs(isLine) do check(covered[line], "line " .. line .. " has a child line") end
check(D.parents[2945] == 165, "child line 2945 is Leatherworking")
for id, list in pairs(D.names) do check(isLine[id], "names: " .. id .. " is a line") end

-- In German, by the client's own texts.
local function named(id, en, de) check(D.names[id][1] == en and D.names[id][2] == de, en .. " is " .. de) end
named(171, "Alchemy", "Alchimie")
named(164, "Blacksmithing", "Schmiedekunst")
named(333, "Enchanting", "Verzauberkunst")
named(202, "Engineering", "Ingenieurskunst")
named(165, "Leatherworking", "Lederverarbeitung")
named(197, "Tailoring", "Schneiderei")
named(185, "Cooking", "Kochkunst")
named(129, "First Aid", "Erste Hilfe")
named(182, "Herbalism", "Kräuterkunde")
named(186, "Mining", "Bergbau")
named(393, "Skinning", "Kürschnerei")
named(356, "Fishing", "Angeln")
check(D.icons[165] == 136247, "Leatherworking's icon")

section("Recipe data: every recipe")
local byLine, used, total = {}, {}, 0
local function numberOf(text) return text ~= "" and tonumber(text) or nil end
for _, line in ipairs(D.order) do
	local text = D.recipes[line]
	check(type(text) == "string" and text ~= "", "line " .. line .. " has its string")
	local list, last = {}, 0
	byLine[line] = list
	for recipe in (text .. ";"):gmatch("([^;]*);") do
		total = total + 1
		local spell, item, count, slot, ilvl, quality, low, high, cat, reagents =
			recipe:match("^(%d+):(%d*):(%d*):(%d*):(%d*):(%d*):(%d+):(%d+):(%d*):([%d%*%+]+)$")
		if not spell then
			check(false, "doesn't parse: " .. recipe)
		else
			local id = tonumber(spell)
			if id <= last then check(false, "out of order or repeated: spell " .. spell .. " in line " .. line) end
			last = id
			if (item == "") ~= (count == "") or (count ~= "" and tonumber(count) < 1) then
				check(false, "spell " .. spell .. ": item and count go together, one at least")
			end
			if (slot == "") ~= (ilvl == "") or (slot == "") ~= (quality == "") or (slot ~= "" and item == "") then
				check(false, "spell " .. spell .. ": slot, level and quality go together, with an item")
			end
			if tonumber(low) > tonumber(high) then check(false, "spell " .. spell .. ": low above high") end
			if cat ~= "" then
				used[tonumber(cat)] = true
				if not names(D.categories[tonumber(cat)]) then check(false, "spell " .. spell .. ": category " .. cat .. " has no names") end
			end
			local parsed, seen = {}, {}
			for pair in (reagents .. "+"):gmatch("([^%+]*)%+") do
				local reagent, n = pair:match("^(%d+)%*(%d+)$")
				if not reagent or tonumber(reagent) < 1 or tonumber(n) < 1 or seen[reagent] then
					check(false, "spell " .. spell .. ": reagent " .. pair)
				else
					seen[reagent] = true
					parsed[#parsed + 1] = { tonumber(reagent), tonumber(n) }
				end
			end
			list[id] = { item = numberOf(item), count = numberOf(count), slot = numberOf(slot), ilvl = numberOf(ilvl), quality = numberOf(quality),
				low = tonumber(low), high = tonumber(high), cat = numberOf(cat), reagents = parsed }
		end
	end
end
check(total > 2000, "the recipes are there")
for id, list in pairs(D.categories) do
	check(names(list), "category " .. id .. " has names")
	check(used[id], "category " .. id .. " is used")
end

section("Recipe data: known recipes")
local function recipe(line, spell, item, count, low, high, cat, reagents, what)
	local r = byLine[line][spell]
	check(r, what .. " is there")
	if not r then return end
	check(r.item == item and r.count == count, what .. " makes " .. tostring(count) .. " of " .. tostring(item))
	check(r.low == low and r.high == high, what .. ": skill")
	check(r.cat == cat, what .. ": category")
	local ok = #r.reagents == #reagents
	for i, want in ipairs(reagents) do
		ok = ok and r.reagents[i] and r.reagents[i][1] == want[1] and r.reagents[i][2] == want[2]
	end
	check(ok, what .. ": reagents")
end
recipe(165, 2149, 2302, 1, 40, 70, 2560, { { 2318, 2 }, { 2320, 1 } }, "Handstitched Leather Boots")
recipe(165, 2152, 2304, 1, 30, 60, 2569, { { 2318, 1 } }, "Light Armor Kit")
recipe(165, 2881, 2318, 1, 20, 40, 2550, { { 2934, 3 } }, "Light Leather")
recipe(129, 3275, 1251, 1, 30, 60, 2530, { { 2589, 1 } }, "Linen Bandage")
recipe(202, 3920, 8067, 200, 30, 60, 2528, { { 4357, 1 }, { 2840, 1 } }, "Crafted Light Shot (a stack)")
recipe(202, 3919, 4358, 2, 30, 60, 2516, { { 4357, 1 }, { 2589, 1 } }, "Rough Dynamite (two)")
recipe(333, 25124, 20744, 1, 30, 65, 2492, { { 10940, 1 }, { 17034, 1 }, { 3371, 1 } }, "Minor Wizard Oil (0 in the table means one)")
recipe(202, 3946, 4378, 3, 125, 145, 2516, { { 4377, 2 }, { 2592, 1 } }, "Heavy Dynamite (1 to 5: the middle)")
recipe(197, 12091, 10040, 1, 145, 155, 2590, { { 4339, 5 }, { 8343, 3 }, { 2324, 1 } }, "White Wedding Dress (a gap in the reagent columns)")

local enchant = byLine[333][7418]
check(enchant and not enchant.item and not enchant.count and not enchant.slot, "an enchant makes no item")
local boots = byLine[165][2149]
check(boots.slot == 8 and boots.quality == 1 and boots.ilvl > 0, "the boots' slot, level and quality")
local notSparse = byLine[171][435969]
check(notSparse and notSparse.item == 213372 and not notSparse.slot and not notSparse.ilvl and not notSparse.quality,
	"an item ItemSparse doesn't have: what it makes, no slot, level or quality")
check(byLine[185][818] and not byLine[185][818].item and not byLine[185][818].cat, "Basic Campfire: no item, no category")
check(byLine[197][461692] and byLine[165][461692], "a recipe of two lines is in both (one under the same line twice is once: the order check)")
check(byLine[164][1213492], "Obsidian Reaver, two rows under Blacksmithing")
check(not byLine[165][2108], "a line's own rank has no reagents: not a recipe")

check(D.categories[2560][1] == "Leather Boots" and D.categories[2560][2] == "Lederstiefel", "a category in both languages")
